<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/idempotency.php';send_cors_headers();$auth=require_auth();$userId=auth_user_id($auth);$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET'){$stmt=$db->prepare('SELECT b.*,e.title,e.starts_at,e.ends_at,e.venue_type,e.venue_name,t.name AS ticket_name FROM event_bookings b JOIN events e ON e.id=b.event_id JOIN event_ticket_types t ON t.id=b.ticket_type_id WHERE b.user_id=:user ORDER BY b.created_at DESC');$stmt->execute(['user'=>$userId]);json_response(200,['success'=>true,'bookings'=>$stmt->fetchAll()]);}if($method==='POST'){$body=get_json_body();$ticketId=trim((string)($body['ticket_type_id']??''));$qty=(int)($body['quantity']??0);$attendees=(array)($body['attendees']??[]);if($qty<1||$qty>10||count($attendees)!==$qty)json_response(422,['success'=>false,'message'=>'Valid quantity and attendee details are required.']);$idem=begin_idempotent_request('event.booking',['type'=>'customer','id'=>$userId],$body);$db->beginTransaction();try{$stmt=$db->prepare('SELECT t.*,e.status AS event_status,e.booking_opens_at,e.booking_closes_at FROM event_ticket_types t JOIN events e ON e.id=t.event_id WHERE t.id=:id FOR UPDATE');$stmt->execute(['id'=>$ticketId]);$ticket=$stmt->fetch();if(!$ticket||$ticket['event_status']!=='published'||$ticket['status']!=='active'||strtotime($ticket['sales_start_at'])>time()||strtotime($ticket['sales_end_at'])<time())json_response(422,['success'=>false,'message'=>'Tickets are not currently available.']);if($qty<(int)$ticket['min_per_booking']||$qty>(int)$ticket['max_per_booking']||(int)$ticket['capacity']-(int)$ticket['sold_quantity']-(int)$ticket['reserved_quantity']<$qty)json_response(409,['success'=>false,'message'=>'Requested ticket quantity is not available.']);foreach($attendees as $person)if(mb_strlen(trim((string)($person['name']??'')))<2)json_response(422,['success'=>false,'message'=>'Every attendee needs a valid name.']);$id=uuid_string();$number='EVT-'.gmdate('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,8));$total=round((float)$ticket['price']*$qty,2);$status=$total<=0?'confirmed':'payment_pending';$db->prepare('INSERT INTO event_bookings (id,booking_number,event_id,ticket_type_id,user_id,quantity,unit_price,total_amount,attendee_json,status,reservation_expires_at,created_at,confirmed_at) VALUES (:id,:number,:event,:ticket,:user,:qty,:price,:total,:attendees,:status,IF(:status="payment_pending",DATE_ADD(UTC_TIMESTAMP(),INTERVAL 15 MINUTE),NULL),UTC_TIMESTAMP(),IF(:status="confirmed",UTC_TIMESTAMP(),NULL))')->execute(['id'=>$id,'number'=>$number,'event'=>$ticket['event_id'],'ticket'=>$ticketId,'user'=>$userId,'qty'=>$qty,'price'=>$ticket['price'],'total'=>$total,'attendees'=>json_encode($attendees,JSON_UNESCAPED_UNICODE),'status'=>$status]);$db->prepare('UPDATE event_ticket_types SET reserved_quantity=reserved_quantity+:qty,updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['qty'=>$qty,'id'=>$ticketId]);if($status==='confirmed')$db->prepare('UPDATE event_ticket_types SET reserved_quantity=reserved_quantity-:qty,sold_quantity=sold_quantity+:qty WHERE id=:id')->execute(['qty'=>$qty,'id'=>$ticketId]);audit_event('customer.event_booking_created','event_booking',$id,['quantity'=>$qty,'total'=>$total]);$response=['success'=>true,'message'=>$status==='confirmed'?'Booking confirmed.':'Seats reserved for 15 minutes. Complete payment.','booking'=>['id'=>$id,'booking_number'=>$number,'status'=>$status,'total_amount'=>$total]];finish_idempotent_request((int)$idem['id'],201,$response);$db->commit();json_response(201,$response);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}json_response(405,['success'=>false,'message'=>'Method not allowed.']);
